from collections import Counter

def runs(values, bg):
    out=[]; i=0
    while i<len(values):
        if values[i]==bg:
            i+=1; continue
        j=i+1
        while j<len(values) and values[j]==values[i]: j+=1
        if j-i>=2: out.append((i,j,values[i]))
        i=j
    return out

def transform(grid):
    src=[row[:] for row in grid]
    out=[row[:] for row in grid]
    h,w=len(src),len(src[0])
    bg=Counter(v for row in src for v in row).most_common(1)[0][0]
    horiz=[]
    for a,b,col in runs(src[0],bg): horiz.append(('top',a,b,col))
    for a,b,col in runs(src[-1],bg): horiz.append(('bottom',a,b,col))
    vert=[]
    for a,b,col in runs([src[r][0] for r in range(h)],bg): vert.append(('left',a,b,col))
    for a,b,col in runs([src[r][-1] for r in range(h)],bg): vert.append(('right',a,b,col))
    dots=[(r,c,src[r][c]) for r in range(1,h-1) for c in range(1,w-1) if src[r][c]!=bg]
    if not dots: return out
    ink=Counter(v for _,_,v in dots).most_common(1)[0][0]
    # For each pair of opposite edge bars, activate the offsets containing an
    # interior marker, and project rays from both bars at those offsets.
    for bars,axis in ((horiz,'col'),(vert,'row')):
        first=[b for b in bars if b[0] in ('top','left')]
        second=[b for b in bars if b[0] in ('bottom','right')]
        for s1 in first:
            for s2 in second:
                if s1[2]-s1[1] != s2[2]-s2[1]: continue
                offsets=set()
                for r,c,_ in dots:
                    q=c if axis=='col' else r
                    if s1[1]<=q<s1[2]: offsets.add(q-s1[1])
                    if s2[1]<=q<s2[2]: offsets.add(q-s2[1])
                for off in offsets:
                    for side,a,b,col in (s1,s2):
                        idx=a+off
                        if idx>=b: continue
                        if side=='top': ray=[(r,idx) for r in range(1,h)]
                        elif side=='bottom': ray=[(r,idx) for r in range(h-2,-1,-1)]
                        elif side=='left': ray=[(idx,c) for c in range(1,w)]
                        else: ray=[(idx,c) for c in range(w-2,-1,-1)]
                        hit=next((j for j,(r,c) in enumerate(ray) if src[r][c]!=bg),None)
                        upto=len(ray) if hit is None else hit
                        for r,c in ray[:upto]:
                            if out[r][c]==bg: out[r][c]=ink
                        if hit is not None:
                            r,c=ray[hit]; out[r][c]=4
    return out
